ruleContent.nextContentUrl:
@js:var result = [];
var pages = +String(java.getString('.bookname@text')).match(/\(\d+\/(\d+)\)$/)[1];
for (let i = 2; i <= pages && !/_/.test(baseUrl); i++) {
	result.push(baseUrl.replace(".html", `_${i}.html`));
}
result;

searchUrl:
@js:let data = org.jsoup.Jsoup.parse(java.ajax(source.key)).select('form');
let url = data.attr('action') + "," + JSON.stringify({
  "body": "_token=" + data.select('[name=_token]').attr('value') + "&keyword={{key}}&page={{page}}",
  "method": "POST"
});
url;
